import{_ as e,c as i,o as s,a2 as t}from"./chunks/framework.CIiVzG-O.js";const u=JSON.parse('{"title":"プライバシーの選択","description":"","frontmatter":{},"headers":[],"relativePath":"ja/guide/privacy-choices.md","filePath":"ja/guide/privacy-choices.md","lastUpdated":1793163976000}'),r={name:"ja/guide/privacy-choices.md"};function l(o,a,p,n,h,c){return s(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="プライバシーの選択" tabindex="-1">プライバシーの選択 <a class="header-anchor" href="#プライバシーの選択" aria-label="Permalink to &quot;プライバシーの選択&quot;">​</a></h1><p>NueZip は完全にオフラインのアプリケーションです。すべてのデータがお客様のデバイス上に留まるため、当社が個人情報を収集、販売、または共有することはありません。</p><h2 id="ローカルに保持するデータ" tabindex="-1">ローカルに保持するデータ <a class="header-anchor" href="#ローカルに保持するデータ" aria-label="Permalink to &quot;ローカルに保持するデータ&quot;">​</a></h2><p>NueZip はすべてのデータをお客様の Mac 上にローカルに保存します：</p><ul><li>アプリの設定と構成</li><li>最近使用したファイル一覧</li><li>デバッグログ（有効な場合）</li><li>キーチェーンに保存されたパスワード（保存することを選択した場合）</li></ul><p>これらのデータがサーバーにアップロードされることはありません。</p><h2 id="お客様の権利" tabindex="-1">お客様の権利 <a class="header-anchor" href="#お客様の権利" aria-label="Permalink to &quot;お客様の権利&quot;">​</a></h2><p>NueZip は当社のサーバー上に個人データを収集または保存しないため、当社がアクセス、削除、または転送できる個人データは存在しません。すべてのデータは、アプリ内で直接管理するか、アプリのコンテナフォルダを削除することで管理できます：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Containers/com.w3cub.nuezip</span></span></code></pre></div><h2 id="販売しません" tabindex="-1">販売しません <a class="header-anchor" href="#販売しません" aria-label="Permalink to &quot;販売しません&quot;">​</a></h2><p>NueZip はいかなる個人情報も販売しません。いかなる種類のサードパーティのアナリティクス、広告、トラッキングサービスも使用しません。</p><h2 id="お問い合わせ" tabindex="-1">お問い合わせ <a class="header-anchor" href="#お問い合わせ" aria-label="Permalink to &quot;お問い合わせ&quot;">​</a></h2><p>プライバシーの選択についてご質問がある場合は、以下で issue を作成してください： <code>https://github.com/nuezip/nuezip/issues</code></p>',13)])])}const _=e(r,[["render",l]]);export{u as __pageData,_ as default};
